// ssm_s4d.tile - Tile S4D SSM

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <cuda_runtime.h>

#define DIM 18432
#define BLOCK_SIZE 256
#define MAX_ITER 100

__global__ void s4d_kernel(float* A, float* B, float* C, float* Delta, float* x, float* out, int dim) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < dim) {
        float exp_a = expf(A[i]);
        float a_state = exp_a * x[i];
        float b_delta = B[i] * Delta[i];
        float sum_val = a_state + b_delta;
        out[i] = C[i] * sum_val;
    }
}

void s4d_update(float* A, float* B, float* C, float* Delta, float* x, float* out, int dim) {
    float *d_A, *d_B, *d_C, *d_Delta, *d_x, *d_out;
    cudaMalloc((void**)&d_A, dim * sizeof(float));
    cudaMalloc((void**)&d_B, dim * sizeof(float));
    cudaMalloc((void**)&d_C, dim * sizeof(float));
    cudaMalloc((void**)&d_Delta, dim * sizeof(float));
    cudaMalloc((void**)&d_x, dim * sizeof(float));
    cudaMalloc((void**)&d_out, dim * sizeof(float));

    cudaMemcpy(d_A, A, dim * sizeof(float), cudaMemcpyHostToDevice);
    cudaMemcpy(d_B, B, dim * sizeof(float), cudaMemcpyHostToDevice);
    cudaMemcpy(d_C, C, dim * sizeof(float), cudaMemcpyHostToDevice);
    cudaMemcpy(d_Delta, Delta, dim * sizeof(float), cudaMemcpyHostToDevice);
    cudaMemcpy(d_x, x, dim * sizeof(float), cudaMemcpyHostToDevice);

    int num_blocks = (dim + BLOCK_SIZE - 1) / BLOCK_SIZE;
    s4d_kernel<<<num_blocks, BLOCK_SIZE>>>(d_A, d_B, d_C, d_Delta, d_x, d_out, dim);

    cudaMemcpy(out, d_out, dim * sizeof(float), cudaMemcpyDeviceToHost);

    cudaFree(d_A);
    cudaFree(d_B);
    cudaFree(d_C);
    cudaFree(d_Delta);
    cudaFree(d_x);
    cudaFree(d_out);
}

void generate_random_params(float* A, float* B, float* C, float* Delta, float* x, int dim) {
    srand(time(NULL));
    for (int i = 0; i < dim; i++) {
        A[i] = (float)rand() / RAND_MAX * 2.0f - 1.0f;
        B[i] = (float)rand() / RAND_MAX;
        C[i] = (float)rand() / RAND_MAX;
        Delta[i] = (float)rand() / RAND_MAX;
        x[i] = (float)rand() / RAND_MAX * 2.0f - 1.0f;
    }
}

float evaluate_s4d_sequence(float* A, float* B, float* C, float* Delta, float** x_seq, int seq_len, int dim) {
    float total_out = 0.0f;
    float* out = (float*)malloc(dim * sizeof(float));
    for (int t = 0; t < seq_len; t++) {
        s4d_update(A, B, C, Delta, x_seq[t], out, dim);
        float sum_out = 0.0f;
        for (int i = 0; i < dim; i++) {
            sum_out += out[i];
        }
        total_out += sum_out / (float)dim;
    }
    free(out);
    return total_out / (float)seq_len;
}

void free_sequence(float** seq, int seq_len) {
    for (int t = 0; t < seq_len; t++) {
        free(seq[t]);
    }
    free(seq);
}

int main() {
    int dim = DIM;
    int seq_len = 20;
    float *A = (float*)malloc(dim * sizeof(float));
    float *B = (float*)malloc(dim * sizeof(float));
    float *C = (float*)malloc(dim * sizeof(float));
    float *Delta = (float*)malloc(dim * sizeof(float));
    float** x_seq = (float**)malloc(seq_len * sizeof(float*));
    generate_random_params(A, B, C, Delta, NULL, dim);
    for (int t = 0; t < seq_len; t++) {
        x_seq[t] = (float*)malloc(dim * sizeof(float));
        generate_random_params(NULL, NULL, NULL, NULL, x_seq[t], dim);
    }
    float avg_out = evaluate_s4d_sequence(A, B, C, Delta, x_seq, seq_len, dim);
    printf("Average S4D output: %f\n", avg_out);
    float single_out[dim];
    srand(time(NULL));
    float single_x[dim];
    generate_random_params(NULL, NULL, NULL, NULL, single_x, dim);
    auto start = std::chrono::high_resolution_clock::now(); // wait, C++ chrono in C? Use clock
    clock_t start_time = clock();
    for (int iter = 0; iter < MAX_ITER; iter++) {
        s4d_update(A, B, C, Delta, single_x, single_out, dim);
    }
    clock_t end_time = clock();
    double time_elapsed = ((double)(end_time - start_time)) / CLOCKS_PER_SEC / MAX_ITER;
    printf("Time per S4D update: %f seconds\n", time_elapsed);
    free(A);
    free(B);
    free(C);
    free(Delta);
    free_sequence(x_seq, seq_len);
    return 0;
}

