#include <stdlib.h>
#include <math.h>
#include <time.h>
#include <cuda_runtime.h>

#define DIM 18432
#define BLOCK_SIZE 256
#define MAX_ITER 100

__global__ void s4d_kernel(float* A, float* B, float* C, float* Delta, float* x, float* out, int dim) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < dim) {
        float exp_a = expf(A[i]);[1]
        float a_state = exp_a * x[i];[1]
        float b_delta = B[i] * Delta[i];[1]
        float sum_val = a_state + b_delta;[1]
        out[i] = C[i] * sum_val;[1]
    }[1]
}[1]

static inline void cuda_check(cudaError_t err) {
    if (err != cudaSuccess) {
        fprintf(stderr, "CUDA Error: %s (%d)\n", cudaGetErrorString(err), (int)err);[1]
        exit(EXIT_FAILURE);[1]
    }[1]
}[1]

void s4d_update(float* A, float* B, float* C, float* Delta, float* x, float* out, int dim) {
    float *d_A = NULL, *d_B = NULL, *d_C = NULL, *d_Delta = NULL, *d_x = NULL, *d_out = NULL;[1]
    cuda_check(cudaMalloc((void**)&d_A, dim * sizeof(float)));[1]
    cuda_check(cudaMalloc((void**)&d_B, dim * sizeof(float)));[1]
    cuda_check(cudaMalloc((void**)&d_C, dim * sizeof(float)));[1]
    cuda_check(cudaMalloc((void**)&d_Delta, dim * sizeof(float)));[1]
    cuda_check(cudaMalloc((void**)&d_x, dim * sizeof(float)));[1]
    cuda_check(cudaMalloc((void**)&d_out, dim * sizeof(float)));[1]

    cuda_check(cudaMemcpy(d_A, A, dim * sizeof(float), cudaMemcpyHostToDevice));[1]
    cuda_check(cudaMemcpy(d_B, B, dim * sizeof(float), cudaMemcpyHostToDevice));[1]
    cuda_check(cudaMemcpy(d_C, C, dim * sizeof(float), cudaMemcpyHostToDevice));[1]
    cuda_check(cudaMemcpy(d_Delta, Delta, dim * sizeof(float), cudaMemcpyHostToDevice));[1]
    cuda_check(cudaMemcpy(d_x, x, dim * sizeof(float), cudaMemcpyHostToDevice));[1]

    int num_blocks = (dim + BLOCK_SIZE - 1) / BLOCK_SIZE;[1]
    s4d_kernel<<<num_blocks, BLOCK_SIZE>>>(d_A, d_B, d_C, d_Delta, d_x, d_out, dim);[1]
    cuda_check(cudaGetLastError());[1]
    cuda_check(cudaDeviceSynchronize());[1]

    cuda_check(cudaMemcpy(out, d_out, dim * sizeof(float), cudaMemcpyDeviceToHost));[1]

    cuda_check(cudaFree(d_A));[1]
    cuda_check(cudaFree(d_B));[1]
    cuda_check(cudaFree(d_C));[1]
    cuda_check(cudaFree(d_Delta));[1]
    cuda_check(cudaFree(d_x));[1]
    cuda_check(cudaFree(d_out));[1]
}[1]

void generate_random_params(float* A, float* B, float* C, float* Delta, float* x, int dim) {
    time_t seconds = time(NULL);[2]
    srand((unsigned int)seconds);[2]
    for (int i = 0; i < dim; i++) {
        if (A) A[i] = (float)rand() / (float)RAND_MAX * 2.0f - 1.0f;[2]
        if (B) B[i] = (float)rand() / (float)RAND_MAX;[2]
        if (C) C[i] = (float)rand() / (float)RAND_MAX;[2]
        if (Delta) Delta[i] = (float)rand() / (float)RAND_MAX;[2]
        if (x) x[i] = (float)rand() / (float)RAND_MAX * 2.0f - 1.0f;[2]
    }[2]
}[2]

float evaluate_s4d_sequence(float* A, float* B, float* C, float* Delta, float** x_seq, int seq_len, int dim) {
    float total_out = 0.0f;[1]
    float* out = (float*)malloc((size_t)dim * sizeof(float));[1]
    if (!out) {
        fprintf(stderr, "Host allocation failed\n");[1]
        exit(EXIT_FAILURE);[1]
    }[1]
    for (int t = 0; t < seq_len; t++) {
        s4d_update(A, B, C, Delta, x_seq[t], out, dim);[1]
        float sum_out = 0.0f;[1]
        for (int i = 0; i < dim; i++) {
            sum_out += out[i];[1]
        }[1]
        total_out += sum_out / (float)dim;[1]
    }[1]
    free(out);[1]
    return total_out / (float)seq_len;[1]
}[1]

void free_sequence(float** seq, int seq_len) {
    if (!seq) return;[1]
    for (int t = 0; t < seq_len; t++) {
        free(seq[t]);[1]
    }[1]
    free(seq);[1]
}[1]

int main() {
    int dim = DIM;[1]
    int seq_len = 20;[1]

    float *A = (float*)malloc((size_t)dim * sizeof(float));[1]
    float *B = (float*)malloc((size_t)dim * sizeof(float));[1]
    float *C = (float*)malloc((size_t)dim * sizeof(float));[1]
    float *Delta = (float*)malloc((size_t)dim * sizeof(float));[1]
    if (!A || !B || !C || !Delta) {
        fprintf(stderr, "Host allocation failed\n");[1]
        free(A); free(B); free(C); free(Delta);[1]
        return EXIT_FAILURE;[1]
    }[1]

    float** x_seq = (float**)malloc((size_t)seq_len * sizeof(float*));[1]
    if (!x_seq) {
        fprintf(stderr, "Host allocation failed\n");[1]
        free(A); free(B); free(C); free(Delta);[1]
        return EXIT_FAILURE;[1]
    }[1]

    generate_random_params(A, B, C, Delta, NULL, dim);[2]

    for (int t = 0; t < seq_len; t++) {
        x_seq[t] = (float*)malloc((size_t)dim * sizeof(float));[1]
        if (!x_seq[t]) {
            fprintf(stderr, "Host allocation failed\n");[1]
            for (int k = 0; k < t; k++) free(x_seq[k]);[1]
            free(x_seq);[1]
            free(A); free(B); free(C); free(Delta);[1]
            return EXIT_FAILURE;[1]
        }[1]
        generate_random_params(NULL, NULL, NULL, NULL, x_seq[t], dim);[2]
    }[1]

